function generateNetworkLibraryRuntime(enabledModules) {
  const enabledIds = new Set(enabledModules.map((module4) => module4.manifest.id));
  const fragments = Object.entries(RUNTIMES3).filter(([moduleId]) => enabledIds.has(moduleId)).map(([, runtime]) => runtime);
  const needsSockets = ["lingbuilder.net.tcp", "lingbuilder.net.udp", "lingbuilder.net.dns", "lingbuilder.net.mail"].some((moduleId) => enabledIds.has(moduleId));
  return [needsSockets ? SOCKET_SUPPORT : "", ...fragments].filter(Boolean).join("\n");
}

