// src/services/windowDesigner/cdpClientRuntime.ts
function generateCdpClientRuntime(enabledModules) {
  if (!enabledModules.some((module4) => module4.manifest.id === CDP_CLIENT_MODULE_ID)) return "";
  return CDP_JSON_RUNTIME + "\n" + CDP_CLIENT_RUNTIME;
}
function generateCdpClientWindowMethods(enabledModules) {
  if (!enabledModules.some((module4) => module4.manifest.id === CDP_CLIENT_MODULE_ID)) return "";
  return CDP_CLIENT_WINDOW_METHODS;
}
function generateCdpClientGlobalMethods(enabledModules) {
  if (!enabledModules.some((module4) => module4.manifest.id === CDP_CLIENT_MODULE_ID)) return "";
  return CDP_CLIENT_WINDOW_METHODS.replaceAll("cdpClientRuntime_", "g_cdpClientRuntime").replaceAll("cdpClientReturnText_", "g_cdpClientReturnText").replace(/^    /gmu, "static ");
}
function generateCdpClientGlobalMethodDeclarations(enabledModules) {
  if (!enabledModules.some((module4) => module4.manifest.id === CDP_CLIENT_MODULE_ID)) return "";
  return CDP_CLIENT_WINDOW_METHODS.trim().split(/\r?\n/u).map((line) => {
    const normalized = line.trim();
    const signatureEnd = normalized.indexOf(" {");
    if (signatureEnd < 0) throw new Error(`CDP \u5BA2\u6237\u7AEF\u5305\u88C5\u65B9\u6CD5\u7F3A\u5C11\u51FD\u6570\u4F53\uFF1A${normalized}`);
    return `static ${normalized.slice(0, signatureEnd)};`;
  }).join("\n");
}
