function command4(name, parameters, returnType, description, category, example) {
  const placeholders = parameters.map((parameter11, index2) => parameter11.type === "wideString" ? `"$${index2 + 1}"` : "0");
  return {
    name,
    signature: `${name}(${parameters.map((parameter11) => parameter11.name).join(", ")})`,
    description,
    insertText: `${name}(${placeholders.join(", ")})`,
    parameters,
    returnType,
    category,
    example
  };
}
