function generateNewEmojiDataBridgeCpp(program, enabledModules, dataTypes) {
  const used = NEW_EMOJI_DATA_BRIDGE_COMMANDS.some((command8) => program.source.includes(command8));
  if (!used) return "";
  const collectHandlers = (commands) => {
    const names = /* @__PURE__ */ new Set();
    for (const command8 of commands) {
      for (const name of getNewEmojiBoundHandlerNames(program.source, command8)) names.add(name);
    }
    return [...names].flatMap((name) => {
      const method = findLingCppMethod(program, name);
      return method ? [{ name, method }] : [];
    });
  };
  const buildTrampoline = (callback, parameters, callbackType, method) => {
    const binding8 = {
      command: "LB_NE_MsgBox",
      eventName: "Result",
      callbackType,
      method
    };
    return `static void __stdcall ${callback}(${parameters}) {
${generateNewEmojiEventParameterDeclarations(binding8, enabledModules, program.dataTypes)}
${generateNewEmojiMethodBody(method, enabledModules, program.dataTypes)}
}`;
  };
  const resultHandlers = collectHandlers(["NE_\u663E\u793A\u6D88\u606F\u6846", "NE_\u663E\u793A\u786E\u8BA4\u6846"]);
  const exHandlers = collectHandlers(["NE_\u663E\u793A\u6269\u5C55\u6D88\u606F\u6846"]);
  const resultTrampolines = resultHandlers.map((item, index2) => buildTrampoline(
    `LB_NE_MsgBoxResultCb_${index2 + 1}`,
    "int lb_messagebox_id, int lb_result",
    "MessageBoxResultCallback",
    item.method
  ));
  const exTrampolines = exHandlers.map((item, index2) => buildTrampoline(
    `LB_NE_MsgBoxExCb_${index2 + 1}`,
    "int lb_messagebox_id, int lb_action, const unsigned char* lb_value_utf8, int lb_value_utf8_length",
    "MessageBoxExCallback",
    item.method
  ));
  const resultCases = resultHandlers.map((item, index2) => `    if (std::wcscmp(handlerName, L"${escapeWideString(item.name)}") == 0) return LB_NE_MsgBoxResultCb_${index2 + 1};`).join("\n");
  const exCases = exHandlers.map((item, index2) => `    if (std::wcscmp(handlerName, L"${escapeWideString(item.name)}") == 0) return LB_NE_MsgBoxExCb_${index2 + 1};`).join("\n");
  return `${NEW_EMOJI_DATA_BRIDGE_HELPERS}
${resultTrampolines.join("\n\n")}

static LB_NE_MsgBoxResultFn LB_NE_FindMsgBoxResultHandler(const wchar_t* handlerName) {
    if (!handlerName || !*handlerName) return nullptr;
${resultCases}
    return nullptr;
}

${exTrampolines.join("\n\n")}

static LB_NE_MsgBoxExFn LB_NE_FindMsgBoxExHandler(const wchar_t* handlerName) {
    if (!handlerName || !*handlerName) return nullptr;
${exCases}
    return nullptr;
}`;
}
