app.get("/api/solution/watch", async (req, res) => {
  try {
    await getSolutionService().getSolution();
    const solutionDirectory = import_path4.default.join(getRepoWorkspaceRoot(), ".lingbuilder");
    await import_promises50.default.mkdir(solutionDirectory, { recursive: true });
    res.setHeader("Content-Type", "text/event-stream");
    res.setHeader("Cache-Control", "no-cache");
    res.setHeader("Connection", "keep-alive");
    res.flushHeaders();
    let disposed = false;
    let pendingTimer;
    const sendSolutionChange = () => {
      if (disposed) return;
      res.write(`event: solution-change
data: ${JSON.stringify({ reason: "solution-file-changed" })}

`);
    };
    const sendNavigation = async () => {
      if (disposed) return;
      try {
        const navigationPath = import_path4.default.join(solutionDirectory, "ai-bridge", "workbench-navigation.json");
        const navigation = JSON.parse(await import_promises50.default.readFile(navigationPath, "utf8"));
        if (navigation.action !== "open-project" || typeof navigation.requestId !== "string" || typeof navigation.projectId !== "string" || typeof navigation.filePath !== "string") return;
        res.write(`event: workbench-navigation
data: ${JSON.stringify(navigation)}

`);
      } catch (error) {
        if (error?.code !== "ENOENT") console.warn("\u5DE5\u4F5C\u53F0\u5BFC\u822A\u8BF7\u6C42\u8BFB\u53D6\u5931\u8D25\uFF1A", error?.message || error);
      }
    };
    const handleChange = (_eventType, fileName) => {
      const changedName = fileName ? String(fileName).replace(/\\/g, "/") : "";
      if (!changedName || changedName === "solution.json") sendSolutionChange();
      if (changedName === "ai-bridge" || changedName === "ai-bridge/workbench-navigation.json") {
        if (pendingTimer) clearTimeout(pendingTimer);
        pendingTimer = setTimeout(() => {
          pendingTimer = void 0;
          void sendNavigation();
        }, 40);
      }
    };
    const watcher = (0, import_fs.watch)(solutionDirectory, { recursive: true }, handleChange);
    sendSolutionChange();
    await sendNavigation();
    const heartbeat = setInterval(() => res.write(": heartbeat\n\n"), 2e4);
    req.on("close", () => {
      disposed = true;
      if (pendingTimer) clearTimeout(pendingTimer);
      clearInterval(heartbeat);
      watcher.close();
    });
  } catch (error) {
    if (!res.headersSent) res.status(400).json({ ok: false, error: error?.message || "\u89E3\u51B3\u65B9\u6848\u76D1\u542C\u5931\u8D25\u3002" });
    else res.end();
  }
});
